/* IndexedDB commits are atomic. Images are separate blobs, never large localStorage strings. */
(() => {
 'use strict';
 const M=window.Studio;let database,queue=Promise.resolve();const urls=new Map();
 function open(){return new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(Error('当前浏览器无法使用本地数据库。'));const req=indexedDB.open('reborn-studio',1);req.onupgradeneeded=()=>{req.result.createObjectStore('state');req.result.createObjectStore('images');};req.onsuccess=()=>{database=req.result;database.onversionchange=()=>database.close();resolve(database);};req.onerror=()=>reject(req.error);req.onblocked=()=>reject(Error('请关闭其他打开的原型窗口，再重试。'));});}
 function read(store,key){return new Promise((resolve,reject)=>{const tx=database.transaction(store,'readonly');const r=tx.objectStore(store).get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
 function write(store,key,value){return new Promise((resolve,reject)=>{const tx=database.transaction(store,'readwrite');tx.objectStore(store).put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||Error('本地写入失败'));tx.onabort=()=>reject(tx.error||Error('本地写入被中断'));});}
 function commit(state){const saved=M.copy(state);const run=()=>write('state','current',saved);queue=queue.catch(()=>{}).then(run);return queue;}
 async function saveImage(blob,id=M.uid('image')){await write('images',id,blob);urls.set(id,URL.createObjectURL(blob));return id;}
 async function imageURL(id){if(!id)return '';if(urls.has(id))return urls.get(id);const blob=await read('images',id);if(!blob)return '';const u=URL.createObjectURL(blob);urls.set(id,u);return u;}
 function fromDataURL(data){const [header,body]=data.split(',');const bytes=Uint8Array.from(atob(body),c=>c.charCodeAt(0));return new Blob([bytes],{type:header.match(/data:([^;]+)/)?.[1]||'image/jpeg'});}
 async function migrate(state){let raw;try{raw=localStorage.getItem('studio3.h5.iteration3');}catch{return state;}if(!raw)return state;const old=JSON.parse(raw);if(old.version!==3||!Array.isArray(old.works))throw Error('旧版记录无法读取；原数据已保留。');const convert=async w=>{const d=M.fresh('enamel-'+(w.pattern||'magpie'));d.id='legacy-'+(w.id||M.uid());d.lineageId=d.id;Object.assign(d,{title:w.title||'',idea:w.story||'',color:w.cup||'white',scale:w.scale||100,x:w.offset||0,imageName:w.imageName||''});if(w.image&&w.source==='own')d.imageId=await saveImage(fromDataURL(w.image));return d;};for(const w of old.works){const d=await convert(w);if(w.kind==='draft')state.drafts.push(d);else{delete d.past;delete d.future;d.savedAt=w.createdAt||M.now();state.works.push(d);if(w.submission){const snap=await convert(w.submission.snapshot||w);state.submissions.push({id:'legacy-'+w.submission.id,workId:d.id,status:'已提交 · 演示',createdAt:w.submission.createdAt||M.now(),snapshot:snap,consentVersion:'legacy-local'});}}}if(old.current&&(old.current.image||old.current.title||old.current.id)){const d=await convert(old.current);d.id=M.uid('draft');state.drafts.push(d);state.ui.activeDraftId=d.id;}state.favorites=(old.favorites||[]).map(x=>'enamel-'+x).filter(id=>M.items.some(i=>i.id===id));state.legacyImported=true;return state;}
 async function load(){await open();const stored=await read('state','current');if(stored)return M.validate(stored);const s=await migrate(M.blank());await commit(s);return s;}
 async function preload(state){const ids=new Set([...state.drafts,...state.works,...state.submissions.map(x=>x.snapshot)].flatMap(w=>[w.imageId,...(w.past||[]).map(x=>x.imageId),...(w.future||[]).map(x=>x.imageId)]).filter(Boolean));await Promise.all([...ids].map(imageURL));}
 function image(id){return urls.get(id)||'';}
 window.LocalStore={load,commit,preload,saveImage,imageURL,image};
})();
